    {
      "source_id": "h7",
      "actor": "assistant",
      "role": "result",
      "fact": "Order #W5521093 has balance_due of 39.00 and status 'delivered'"
    },
    {
      "source_id": "h4",
      "actor": "assistant",
      "role": "result",
      "fact": "User omar_haddad_4410 owns order #W5521093 and has payment method credit_card_4410221 of type credit_card"
